  "Оқиғаны құра":"拼故事",
  "Суреттерді дұрыс ретімен қой":"把图片按顺序排好",
  "Оқиғаны құра!":"拼故事！",
  "Суреттерді дұрыс ретімен бас":"按正确的顺序点击图片",
  "Барсик сөзсіз, тек суретпен әңгіме айтады! Төмендегі барлық суреттерге қара да, алдымен не болғанын, содан кейін не болғанын ойлан. Дұрыс оқиға шығуы үшін суреттерді ретімен бас. Оқиға құруға дайынсың ба?":"巴雷斯不用语言讲故事——只用图片！看看下面所有的图片，想一想先发生了什么，后发生了什么。按顺序点击图片，拼出正确的故事。准备好拼故事了吗？",
