  "Оқу мен жазу дағдыларын дамытамыз":"发展读写能力",
  "Осы тоқсанның қалған тақырыптары нағыз ауызша сөйлеу мен қолмен жазуды талап етеді — батырма ойындарына айналдырылмайды":"本学季其余主题需要真实的口语和手写——无法做成按钮游戏",
  "Барсик қай сөздер бас әріппен жазылатынын үйренеді! Адам аттары (Айгүл), қала атаулары (Алматы) және жануар лақап аттары (Ақбар) — бас әріппен. Қарапайым сөздер (қала, ит) — кіші әріппен. Сөзді оқы да, дұрыс жауапты тап. Дайынсың ба?":"巴雷斯在学习哪些词用大写字母书写！人名（Айгүл）、城市名（Алматы）和动物昵称（Ақбар）——用大写字母。普通词（қала——城市，ит——狗）——用小写字母。读一读这个词，选出正确答案。准备好了吗？",
