  "Мини-фильм: өсімдік бөліктері!":"视频课：植物的组成部分！",
  "Барсик сені жаратылыстанудан шағын сабаққа шақырады! Сен өсімдік бөліктері туралы біздің ойынымызды ойнадың, енді тамыр, сабақ, жапырақ, гүл және жеміс туралы мини-фильмді қара. Қарауға дайынсың ба?":"巴雷斯邀请你上一节自然科学视频课！你已经玩过我们关于植物组成部分的游戏了——现在来看一个真正的视频课，老师会详细讲解根、茎、叶、花和果实。准备好看了吗？",
