  "Барсик сені цифрлық сауаттылықтан шағын сабаққа шақырады! Сен компьютер құрылғылары туралы біздің ойынымызды ойнадың, енді компьютердің не екенін және оның бөліктері не үшін керек екенін түсіндіретін мини-фильмді қара. Қарауға дайынсың ба?":"巴雷斯邀请你上一节数字素养视频课！你已经玩过我们关于电脑设备的游戏了——现在来看一部动画片，详细讲解什么是电脑，以及它的各个部分有什么用。准备好看了吗？",
  "Видео-сабақ: светофор":"视频课：红绿灯",
