  "Монитор, пернетақта, тышқан...":"显示器、键盘、鼠标……",
  "Компьютер құрылғылары!":"电脑设备！",
  "Бұл құрылғы қалай аталады? Суретті тап":"这个设备叫什么名字？找出图片",
  "Барсик компьютерді зерттейді! Компьютердің әртүрлі құрылғылары бар: монитор суретті көрсетеді, пернетақта әріптерді басу үшін керек, тышқан курсорды басқаруға көмектеседі, ал колонкалар дыбысты ойнатады. Атауға қара да сәйкес суретті тап. Компьютерді зерттеуге дайынсың ба?":"巴雷斯在研究电脑！电脑有不同的设备：显示器用来显示画面，键盘用来打字，鼠标帮助控制光标，音箱用来播放声音。看看名字，找出匹配的图片。准备好研究电脑了吗？",
