  "Жедел қызметтер":"紧急服务",
  "Өрт сөндіру, полиция, жедел жәрдем — қай нөмір?":"消防、警察、救护车——是哪个号码？",
  "Жедел қызметтер!":"紧急服务！",
  "Бұл қызметтің нөмірі қандай?":"这个服务的号码是多少？",
  "Барсик маңызды телефон нөмірлерін біледі! Егер өрт шықса — 101-ге қоңырау шал, полиция керек болса — 102-ге, ал біреуге жаман болып, жедел жәрдем керек болса — 103-ке қоңырау шал. Кез келген апат үшін жалпы нөмір де бар — 112. Суретке қара да дұрыс нөмірді таңда. Маңызды нөмірлерді есте сақтауға дайынсың ба?":"巴雷斯知道重要的电话号码！如果发生火灾——拨打101，如果需要警察——拨打102，如果有人受伤需要救护车——拨打103。还有一个适用于任何紧急情况的通用号码——112。看看图片，选择正确的号码。准备好记住这些重要号码了吗？",
