  "Дүйсенбі, сейсенбі, сәрсенбі...":"星期一、星期二、星期三……",
  "Апта күндері!":"一周的日子！",
  "Апта күндерін ретімен қой":"把一周的日子按顺序排好",
  "Барсик апта күндерін санайды! Апта әрқашан бір ретпен өтеді: дүйсенбі, сейсенбі, сәрсенбі, бейсенбі, жұма, сенбі және жексенбі. Күндерді дүйсенбіден бастап ретімен бас. Апта күндерін ретке қоюға дайынсың ба?":"巴雷斯在数一周的日子！一周总是按同样的顺序进行：星期一、星期二、星期三、星期四、星期五、星期六和星期日。从星期一开始，按顺序点击这些日子。准备好把一周的日子排好顺序了吗？",
  "Жол белгілері":"交通标志",
  "Светофор, СТОП белгісі...":"红绿灯、停车标志……",
  "Жол белгілері!":"交通标志！",
  "Бұл белгі нені білдіреді? Оқы да суретті таңда":"这个标志是什么意思？读一读，选出图片",
  "Барсик жол белгілерін үйренеді! Әр белгінің өз мағынасы бар: светофор қозғалысты реттейді, СТОП белгісі тоқтауды айтады, балалар суреті бар белгі жаяу жүргіншілер өтетін жерді ескертеді. Белгілерді білу жолда қауіпсіз болуға көмектеседі. Сипаттамаға қара да керекті белгіні тап. Жол белгілерін үйренуге дайынсың ба?":"巴雷斯在学习交通标志！每个标志都有它的意思：红绿灯用来指挥交通，停车标志告诉你要停下来，带有儿童图案的标志提醒你注意人行横道。认识这些标志能帮助你在路上更安全。看看描述，找出正确的标志。准备好学习交通标志了吗？",
  "ЖАЯУ ЖҮРГІНШІЛЕР ӨТЕТІН ЖЕР":"人行横道",
