  "АВТОБУС АЯЛДАМАСЫ":"公交车站",
  "ТҰРАҚ":"停车场",
  "Қазақстан туы":"哈萨克斯坦国旗",
  "Өз еліңнің туын таны":"认识你祖国的国旗",
  "Қазақстан туы!":"哈萨克斯坦国旗！",
  "Бұл Қазақстанның туы ма, әлде басқа елдікі ме?":"这是哈萨克斯坦的国旗，还是别的国家的？",
  "Барсик өз елімен мақтанады! Қазақстанның өзіндік ерекше туы бар — көк түсті, ортасында күн мен қыран бейнеленген. Басқа елдердің туы мүлдем басқаша. Туға қара да ойлан: бұл Қазақстанның туы ма, әлде басқа елдікі ме? Туды тануға дайынсың ба?":"巴雷斯为自己的祖国感到自豪！哈萨克斯坦有自己特别的国旗——天蓝色，中间有太阳和雄鹰。其他国家的国旗完全不同。看看这面旗，想一想：这是哈萨克斯坦的国旗，还是别的国家的？准备好认国旗了吗？",
  "Басқа ел":"别的国家",
  "Мезгілдер мен демалыс":"季节与活动",
  "Қыс, көктем, жаз, күз — немен айналысамыз?":"冬天、春天、夏天、秋天——做什么？",
  "Мезгілдер мен демалыс!":"季节与活动！",
  "Осы мезгілде немен айналысуға болады? Суретті тап":"这个季节可以做什么？找出图片",
  "Барсик әр мезгілде әртүрлі демалуды жақсы көреді! Қыста шаңғы тебу керемет, көктемде — велосипед тебу, жазда — жүзу, ал күзде мектепке жиналатын кез. Мезгілге қара да сәйкес шаруаны тап. Әр маусымда немен айналысатынымызды білуге дайынсың ба?":"巴雷斯喜欢在不同的季节以不同的方式休息！冬天滑雪很棒，春天骑自行车，夏天游泳，秋天该准备上学了。看看这个季节，找出相应的活动。准备好了解不同季节该做什么了吗？",
  "Аспаптар, әндер, ырғақ":"乐器、歌曲、节奏",
